"""Build the generated files of the SAM 2.1 pipeline from their sources.

Sources (edit these):  cells/        the pipeline notebook, one file per cell
                       demo_cells/   the short demo notebook
Generated (do not edit by hand):
  sam2_pipeline/notebooks/MSU_FRUIT_SAM2_pipeline.ipynb   the full notebook (Colab / Jupyter / OnDemand)
  sam2_pipeline/fruit_sam2.py                             the notebook's tool cells as one module (fruit.py, HPCC jobs)
  demo.ipynb                                              the quick demo at the repository root

Inside the repository, run from anywhere:   python sam2_pipeline/source/build.py
"""
import ast
import shutil
import sys
from pathlib import Path

import nbformat as nbf

HERE = Path(__file__).resolve().parent
CELLS, DEMO_CELLS = HERE / "cells", HERE / "demo_cells"
DEV = (HERE / "static").exists()          # the development copy also assembles the whole repository tree
REPO = Path(sys.argv[1]) if len(sys.argv) > 1 else (HERE / "out" / "repo" if DEV else HERE.parent.parent)
PIPE = REPO / "sam2_pipeline"

# Cells that hold definitions only. Together they are the module the command line imports.
MODULE_CELLS = ["030", "040", "042", "044", "046", "048", "050", "052", "054"]

MODULE_HEADER = '''"""MSU FRUIT · SAM 2.1 pipeline as one importable module.

GENERATED by source/build.py from the notebook's tool cells, so the notebook and the HPCC batch jobs run
exactly the same code. Edit source/cells/, then rebuild; do not edit this file by hand.

    import fruit_sam2 as F
    F.use_project("data/my_project")         # videos/, dataset/, predictions/, models/, results/
    F.finetune("grapes_v1", steps=3000)
    F.benchmark(F.load_lineup("configs/lineup.yaml"))

The command-line front end is fruit.py; the SLURM job scripts in hpcc/ call it.
"""
# ---- defaults the notebook's settings form (cell A) would set --------------------------------------
_DEFER_PROJECT = True          # no project folder until use_project() is called
PROJECT_NAME = "msu_fruit_sam2"
DEMO = False
SAVE_TO_DRIVE = False
SAM2_SIZE = "base_plus"
OBJECT_NAME = "grape cluster"
PROJECT_DIR = ""
'''


def notebook(cell_dir, path, colab_gpu=True):
    cells = []
    for f in sorted(p for p in cell_dir.iterdir() if p.suffix in (".py", ".md")):
        text = f.read_text().rstrip() + "\n"
        if f.suffix == ".md":
            cells.append(nbf.v4.new_markdown_cell(text.rstrip(), id=f.stem))     # fixed ids: rebuilds give
        else:                                                                   # identical files, clean git diffs
            ast.parse(text, filename=f.name)                        # fail the build on a syntax error
            c = nbf.v4.new_code_cell(text.rstrip(), id=f.stem)
            if text.startswith("#@title"):
                c.metadata["cellView"] = "form"                     # Colab: show the title and form, fold the code
            c.metadata["source_file"] = f.name
            cells.append(c)
    meta = {"kernelspec": {"display_name": "Python 3", "language": "python", "name": "python3"},
            "language_info": {"name": "python"}}
    if colab_gpu:
        meta.update({"accelerator": "GPU", "colab": {"provenance": [], "gpuType": "T4", "toc_visible": True}})
    nb = nbf.v4.new_notebook(cells=cells, metadata=meta)
    nbf.validate(nb)
    path.parent.mkdir(parents=True, exist_ok=True)
    nbf.write(nb, path)
    print(f"{path.relative_to(REPO)}  ·  {len(cells)} cells")


def module(path):
    parts = [MODULE_HEADER]
    for prefix in MODULE_CELLS:
        f = next(CELLS.glob(prefix + "_*.py"))
        parts.append(f"\n# {'=' * 100}\n# from source/cells/{f.name}\n# {'=' * 100}\n{f.read_text().rstrip()}\n")
    code = "".join(parts)
    ast.parse(code, filename=path.name)
    path.write_text(code)
    print(f"{path.relative_to(REPO)}  ·  {len(code.splitlines())} lines")


def assemble_dev_tree():
    """Development copy only: hand-written files and these sources go into the repository tree."""
    for f in sorted((HERE / "static").rglob("*")):
        if f.is_file() and "__pycache__" not in f.parts:
            dst = REPO / f.relative_to(HERE / "static")
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(f, dst)
    src = PIPE / "source"
    shutil.rmtree(src, ignore_errors=True)
    for d in ("cells", "demo_cells"):
        shutil.copytree(HERE / d, src / d)
    shutil.copy2(Path(__file__), src / "build.py")
    for sh_file in (PIPE / "hpcc").glob("*.s[hb]"):
        sh_file.chmod(0o755)
    ast.parse((PIPE / "fruit.py").read_text())


if __name__ == "__main__":
    if DEV:
        shutil.rmtree(REPO, ignore_errors=True)          # start clean, so removed files do not linger
        assemble_dev_tree()
    notebook(CELLS, PIPE / "notebooks" / "MSU_FRUIT_SAM2_pipeline.ipynb")
    notebook(DEMO_CELLS, REPO / "demo.ipynb", colab_gpu=False)
    module(PIPE / "fruit_sam2.py")
